"use client";

import { useEffect, useState } from "react";

interface Post {
    id: string;
    slug: string;
    title: string;
    excerpt: string;
    imageUrl?: string;
    createdAt: string;
    type: string;
    author: {
        name: string;
    }
}
const demoPosts: Post[] = [
    { id: "1", slug: "demo-1", title: "Олон улсын зуслангийн эрдэмтэн судлаачдын хурал болно", excerpt: "Ази номхон далайн орнуудын болон бусад олон улсын судлаачид оролцох уг хурлын бүртгэл эхэллээ.", createdAt: "2024-03-01T00:00:00Z", type: "NEWS", author: { name: "Админ" } },
    { id: "2", slug: "demo-2", title: "Артектай хамтран ажиллах санамж бичиг зурлаа", excerpt: "Монголын хүүхэд багачуудыг ОХУ-ын Хар тэнгисийн эрэгт байрлах дэлхийд танигдсан Артек зусланд амраах хөтөлбөрийг албан ёсоор эхлүүллээ.", createdAt: "2024-03-05T00:00:00Z", type: "NEWS", author: { name: "Админ" } },
    { id: "3", slug: "demo-3", title: "Зуслангийн удирдлага, багш нарын сургалт", excerpt: "Зуны амралт эхлэхээс өмнө зуслангийн багш, ажилчдад зориулсан 3 өдрийн сургалтыг зохион байгууллаа.", createdAt: "2024-03-10T00:00:00Z", type: "NEWS", author: { name: "С.Батбилэг" } },
];

import Link from "next/link";

export default function NewsPage() {
    const [posts, setPosts] = useState<Post[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchPosts() {
            try {
                const response = await fetch("/api/posts?type=NEWS");
                const data = await response.json();
                if (Array.isArray(data)) {
                    setPosts(data.length > 0 ? data : demoPosts);
                }
            } catch (error) {
                console.error("Failed to load news", error);
            } finally {
                setLoading(false);
            }
        }

        fetchPosts();
    }, []);

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString('mn-MN');
    };

    return (
        <div className="container mx-auto px-4 py-12 md:py-24">
            <div className="space-y-4 text-center mb-12">
                <h1 className="text-4xl font-bold tracking-tighter sm:text-5xl text-primary">Мэдээ, Мэдээлэл</h1>
                <p className="text-lg text-muted-foreground">
                    Цаг үеийн болон байгууллагын онцлох мэдээ.
                </p>
            </div>

            {loading ? (
                <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
                </div>
            ) : posts.length > 0 ? (
                <div className="grid gap-8 md:grid-cols-2 lg:grid-cols-3">
                    {posts.map((post) => (
                        <Link href={`/news/${post.slug || post.id}`} key={post.id}>
                            <article className="group flex flex-col space-y-2 h-full cursor-pointer hover:bg-slate-50 transition-colors p-3 -m-3 rounded-xl">
                                <div className="aspect-video w-full rounded-lg bg-slate-100 relative overflow-hidden flex items-center justify-center">
                                    {post.imageUrl ? (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img src={post.imageUrl} alt={post.title} className="w-full h-full object-cover transition-transform group-hover:scale-105 duration-300" />
                                    ) : (
                                        <svg className="w-12 h-12 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 002-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>
                                    )}
                                </div>
                                <div className="space-y-1 flex-1">
                                    <h3 className="text-xl font-bold leading-tight group-hover:text-primary transition-colors line-clamp-2 mt-2">
                                        {post.title}
                                    </h3>
                                    <p className="text-muted-foreground line-clamp-3 text-sm mt-2">
                                        {post.excerpt || "Дэлгэрэнгүйг энд дарж орж үзнэ үү."}
                                    </p>
                                </div>
                                <div className="flex items-center space-x-2 text-xs text-muted-foreground mt-4 border-t pt-3">
                                    <div className="font-semibold">{post.author?.name || "Админ"}</div>
                                    <div>•</div>
                                    <div>{formatDate(post.createdAt)}</div>
                                </div>
                            </article>
                        </Link>
                    ))}
                </div>
            ) : (
                <div className="text-center py-20 border rounded-lg bg-slate-50">
                    <h3 className="text-lg font-medium text-slate-600">Одоогоор мэдээ оруулаагүй байна.</h3>
                </div>
            )}
        </div>
    );
}
